// Generates the @oip/part-sdk package from the source-of-truth types in src/core:
//
//   index.d.ts            the BEHAVIOR surface (definePart, ctx) - lifted from src/core/parts/partApi.ts
//   manifest.d.ts         the MANIFEST surface (manifest.json / rig.json: geometry, links, joints, assets,
//                         materials) - the types-only half of src/core/parts/partPackage.ts
//   manifest.schema.json  the same manifest as JSON Schema, so an editor completes and checks a
//                         manifest.json (`"$schema": ".../manifest.schema.json"`) the way it does behavior.js
//
// The SDK an external author installs is types-only: the runtime injects the `definePart` global, so there
// is nothing to ship but declarations. Rather than hand-maintain a copy (which would drift), we emit the
// core project's declarations with `tsc -b` and lift them into the package. global.d.ts, package.json (except its
// version, which follows the Part SDK level: step 8) and README.md are authored by hand and committed as-is - safe
// for global.d.ts because it declares the global
// AS the generated `DefinePart` alias (no copied signature to drift; a hand-copied signature drifted once
// when the lamps `L` type param landed).
//
// The manifest's types are lifted alongside partApi's: the manifest is half of every part, and all of an
// imported model's, and typed only inside src/ it cost two cold-start agent trials 15+ minutes each grepping
// partPackage.ts for the rig schema. That is what manifest.d.ts is for.
//
// Run: npm run build-part-sdk            (re-run after changing partApi.ts or partPackage.ts's types)
//      npm run build-part-sdk -- --check (exit 1 if the committed package is stale - the drift guard)

import { execSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import ts from 'typescript'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = resolve(root, 'packages/part-sdk')
const check = process.argv.includes('--check')

// 1. Emit fresh declarations for the core project (the source of truth, gitignored under .types/).
console.log('· building core declarations (tsc -b src/core)…')
execSync('npx tsc -b src/core', { cwd: root, stdio: 'inherit' })

const readEmitted = (name) =>
  readFileSync(resolve(root, `.types/core/parts/${name}.d.ts`), 'utf8')
    .replace(/\r\n/g, '\n')
    .replace(/^\/\/# sourceMappingURL=.*$/m, '')
    .trimEnd()

const outputs = new Map()

// 2. index.d.ts - partApi's declarations whole, plus a re-export of the manifest types so one import names both.
// partApi imports manifest types from partPackage (PartDefinition.manifest / rig), which the SDK holds in manifest.d.ts.
const apiSource = ts.createSourceFile('partApi.d.ts', readEmitted('partApi'), ts.ScriptTarget.ES2022, true)
let apiText = apiSource.text
for (const st of [...apiSource.statements].reverse()) {
  if (!ts.isImportDeclaration(st)) continue
  const from = st.moduleSpecifier.text
  if (from !== './partPackage') throw new Error(`partApi.d.ts imports ${from}; teach build-part-sdk.mjs where it lives in the SDK`)
  apiText = apiText.slice(0, st.moduleSpecifier.getStart()) + "'./manifest'" + apiText.slice(st.moduleSpecifier.getEnd())
}
outputs.set(
  'index.d.ts',
  [
    '/// <reference path="./global.d.ts" />',
    '// GENERATED by scripts/build-part-sdk.mjs from src/core/parts/partApi.ts - do not edit by hand.',
    '// Re-run `npm run build-part-sdk` after changing the part SDK surface.',
    '',
    apiText,
    '',
    '// The manifest half of a part (manifest.json / rig.json) - see manifest.d.ts.',
    "export * from './manifest';",
    '',
  ].join('\n'),
)

// 3. manifest.d.ts - partPackage's TYPES only. Its functions are the app's validators and editors, not an
// author surface, so they're dropped statement by statement (a statement's full text carries its JSDoc).
const pkgSource = ts.createSourceFile('partPackage.d.ts', readEmitted('partPackage'), ts.ScriptTarget.ES2022, true)
const kept = []
for (const st of pkgSource.statements) {
  if (ts.isImportDeclaration(st)) {
    const from = st.moduleSpecifier.text
    if (from !== './partApi') throw new Error(`partPackage.d.ts imports ${from}; teach build-part-sdk.mjs where it lives in the SDK`)
    kept.push(st.getFullText().replace("'./partApi'", "'./index'").trim())
  } else if (ts.isInterfaceDeclaration(st) || ts.isTypeAliasDeclaration(st)) {
    kept.push(st.getFullText().trim())
  }
}
outputs.set(
  'manifest.d.ts',
  [
    '// GENERATED by scripts/build-part-sdk.mjs from src/core/parts/partPackage.ts (types only) - do not edit by hand.',
    '//',
    '// The MANIFEST half of a part: the `manifest.json` (or an example\'s `rig.json`) that sits beside',
    '// `behavior.js`. Its type is {@link PackageManifest}; the fields baked FROM the behavior (params,',
    '// interactive) are not in it - the script is their source of truth. JSON Schema: manifest.schema.json.',
    '',
    kept.join('\n\n'),
    '',
    '// The connector types the manifest\'s `snap` is made of, declared in index.d.ts (the script\'s `geometry()` and',
    '// `ctx` share some of them) and re-exported here so the manifest\'s whole vocabulary is in one file.',
    "export type { SnapChain, SnapEdgeMount, SnapMount, SnapParamOffset, SnapSpec, SnapSurface, SnapTile, SnapTrack } from './index';",
    '',
  ].join('\n'),
)

// 4. manifest.schema.json - PackageManifest walked through the type checker. Named interfaces/aliases become
// $defs (so a RigLink reads as a RigLink), JSDoc becomes `description`, a union of literals becomes `enum`.
outputs.set('manifest.schema.json', JSON.stringify(manifestSchema(), null, 2) + '\n')

function manifestSchema() {
  const file = resolve(root, 'src/core/parts/partPackage.ts')
  const program = ts.createProgram([file], { strict: true, target: ts.ScriptTarget.ES2022, noEmit: true, skipLibCheck: true })
  const checker = program.getTypeChecker()
  const sf = program.getSourceFile(file)
  const named = new Map() // alias/interface name → declaration node, for the ones declared in core
  const collect = (source) => {
    for (const st of source.statements) {
      if (ts.isInterfaceDeclaration(st) || ts.isTypeAliasDeclaration(st)) named.set(st.name.text, st)
    }
  }
  collect(sf)
  collect(program.getSourceFile(resolve(root, 'src/core/parts/partApi.ts')))
  const defs = {}
  // JSDoc comes back with the SOURCE file's line endings, and a CRLF working copy (a Windows checkout, whatever
  // .gitattributes says) would write `\r\n` INTO the JSON strings, which --check's CRLF normalisation can't see:
  // green here, stale on CI's LF checkout.
  const doc = (symbol) => {
    const text = ts.displayPartsToString(symbol?.getDocumentationComment(checker) ?? []).replace(/\r\n?/g, '\n').trim()
    return text ? { description: text } : {}
  }
  const nameOf = (type) => {
    const sym = type.aliasSymbol ?? type.getSymbol()
    const name = sym?.getName()
    return name && named.has(name) && !type.aliasTypeArguments?.length ? name : undefined
  }
  const ref = (type, seen) => {
    const name = nameOf(type)
    if (!name) return walk(type, seen)
    if (!(name in defs)) {
      defs[name] = {} // placeholder: recursion (RigLink → …) resolves to the $ref
      const decl = named.get(name)
      const sym = checker.getSymbolAtLocation(decl.name)
      defs[name] = { ...doc(sym), ...walk(type, seen) }
    }
    return { $ref: `#/$defs/${name}` }
  }
  const walk = (type) => {
    if (type.flags & ts.TypeFlags.StringLiteral) return { const: type.value }
    if (type.flags & ts.TypeFlags.NumberLiteral) return { const: type.value }
    if (type.flags & ts.TypeFlags.BooleanLiteral) return { const: checker.typeToString(type) === 'true' }
    if (type.flags & ts.TypeFlags.String) return { type: 'string' }
    if (type.flags & ts.TypeFlags.Number) return { type: 'number' }
    if (type.flags & ts.TypeFlags.Boolean) return { type: 'boolean' }
    if (type.flags & (ts.TypeFlags.Any | ts.TypeFlags.Unknown)) return {}
    if (type.isUnion()) {
      const members = type.types.filter((t) => !(t.flags & ts.TypeFlags.Undefined))
      if (members.length === 2 && members.every((t) => t.flags & ts.TypeFlags.BooleanLiteral)) return { type: 'boolean' }
      if (members.every((t) => t.isLiteral())) return { enum: members.map((t) => t.value) }
      if (members.length === 1) return ref(members[0])
      // A union discriminated by `kind` (RigShape, PartPackageGeometry) becomes if/then per kind rather than
      // anyOf: anyOf reports EVERY branch's mismatch (a rig reads as "missing length" from the deck branch),
      // where if/then reports only the errors of the kind the manifest actually declares.
      const kinds = members.map((t) => {
        const k = t.getProperty?.('kind')
        const kt = k && checker.getTypeOfSymbolAtLocation(k, k.valueDeclaration ?? sf)
        return kt && kt.flags & ts.TypeFlags.StringLiteral ? kt.value : undefined
      })
      if (kinds.every((k) => k !== undefined) && new Set(kinds).size === kinds.length) {
        return {
          type: 'object',
          required: ['kind'],
          properties: { kind: { enum: kinds } },
          allOf: members.map((t, i) => ({ if: { properties: { kind: { const: kinds[i] } } }, then: ref(t) })),
        }
      }
      return { anyOf: members.map((t) => ref(t)) }
    }
    // An intersection (`PartBounds & { floorY? }`) falls through to the object walk, which reads the merged
    // property set: allOf with additionalProperties:false on each side would reject the other side's keys.
    if (checker.isTupleType(type)) {
      const items = checker.getTypeArguments(type).map((t) => ref(t))
      return { type: 'array', prefixItems: items, minItems: items.length, maxItems: items.length }
    }
    if (checker.isArrayType(type)) return { type: 'array', items: ref(checker.getTypeArguments(type)[0]) }
    const out = { type: 'object', properties: {}, additionalProperties: false }
    const required = []
    for (const prop of checker.getPropertiesOfType(type)) {
      const decl = prop.valueDeclaration ?? prop.declarations?.[0]
      const pt = checker.getTypeOfSymbolAtLocation(prop, decl ?? sf)
      out.properties[prop.getName()] = { ...doc(prop), ...ref(pt) }
      if (!(prop.flags & ts.SymbolFlags.Optional)) required.push(prop.getName())
    }
    const index = checker.getIndexInfoOfType(type, ts.IndexKind.String)
    if (index) out.additionalProperties = ref(index.type)
    if (required.length > 0) out.required = required
    return out
  }
  const manifestDecl = named.get('PackageManifest')
  const manifestType = checker.getTypeAtLocation(manifestDecl.name)
  const body = walk(manifestType)
  // `$schema` is how a manifest.json points an editor at this file; allow it rather than flag it.
  body.properties = { $schema: { type: 'string' }, ...body.properties }
  return {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    $id: 'https://www.openindustryproject.org/part-sdk/manifest.schema.json',
    title: 'OIP part manifest',
    description:
      'GENERATED by scripts/build-part-sdk.mjs from src/core/parts/partPackage.ts. The manifest.json of a part folder (manifest.json + behavior.js). Structural only: `npm run check-part -- <folder>` also bakes the behavior and checks the references between them.',
    ...body,
    $defs: defs,
  }
}

// 5. The generated declarations must COMPILE, as an author's editor will read them. Fresh is not enough: a type in
// partPackage.ts that names one of its CONSTANTS (`format: typeof PACKAGE_FORMAT`) is lifted without the
// constant, since step 3 keeps types only, and --check passed the broken manifest.d.ts because it matched. Checked
// from memory before anything is written, so a broken package is never written either.
{
  const virtual = new Map([...outputs].filter(([n]) => n.endsWith('.d.ts')).map(([n, c]) => [resolve(outDir, n), c]))
  const opts = {
    strict: true,
    noEmit: true,
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    lib: ['lib.es2022.d.ts'],
    types: [],
  }
  const host = ts.createCompilerHost(opts)
  const { fileExists, readFile, getSourceFile } = host
  host.fileExists = (f) => virtual.has(resolve(f)) || fileExists.call(host, f)
  host.readFile = (f) => virtual.get(resolve(f)) ?? readFile.call(host, f)
  host.getSourceFile = (f, lang, ...rest) =>
    virtual.has(resolve(f)) ? ts.createSourceFile(f, virtual.get(resolve(f)), lang) : getSourceFile.call(host, f, lang, ...rest)
  const diagnostics = ts.getPreEmitDiagnostics(ts.createProgram([resolve(outDir, 'index.d.ts')], opts, host))
  if (diagnostics.length > 0) {
    console.error('✗ the generated declarations do not compile:')
    console.error(ts.formatDiagnostics(diagnostics, { getCanonicalFileName: (f) => f, getCurrentDirectory: () => root, getNewLine: () => '\n' }))
    process.exit(1)
  }
  console.log('✓ the generated declarations compile')
}

// 6. Write, or in --check mode compare.
mkdirSync(outDir, { recursive: true })
let stale = 0
for (const [name, contents] of outputs) {
  const path = resolve(outDir, name)
  if (check) {
    const current = existsSync(path) ? readFileSync(path, 'utf8').replace(/\r\n/g, '\n') : null
    if (current !== contents) {
      console.error(`✗ packages/part-sdk/${name} is stale - run \`npm run build-part-sdk\``)
      stale++
    }
  } else {
    writeFileSync(path, contents)
    console.log(`✓ wrote packages/part-sdk/${name}`)
  }
}
// 7. The schema must accept every manifest the repo ships - the built-ins and the example projects' parts. A
// schema that rejects a real part (a field the type forgot, an intersection gone wrong) would teach every
// editor and agent that reads it that a working part is broken.
const { checkManifestSchema } = await import('./lib/manifestSchema.mjs')
const schema = JSON.parse(outputs.get('manifest.schema.json'))
const shipped = []
const partsRoot = resolve(root, 'examples/parts')
for (const d of readdirSync(partsRoot, { withFileTypes: true }).filter((e) => e.isDirectory())) {
  for (const f of ['rig.json', 'manifest.json']) if (existsSync(resolve(partsRoot, d.name, f))) shipped.push(`examples/parts/${d.name}/${f}`)
}
const projectsRoot = resolve(root, 'examples/projects')
for (const p of existsSync(projectsRoot) ? readdirSync(projectsRoot) : []) {
  const pr = resolve(projectsRoot, p, 'parts')
  for (const d of existsSync(pr) ? readdirSync(pr) : []) if (existsSync(resolve(pr, d, 'manifest.json'))) shipped.push(`examples/projects/${p}/parts/${d}/manifest.json`)
}
let rejected = 0
for (const rel of shipped) {
  const errors = checkManifestSchema(JSON.parse(readFileSync(resolve(root, rel), 'utf8')), schema)
  if (errors.length === 0) continue
  rejected++
  console.error(`✗ manifest.schema.json rejects the shipped ${rel}:`)
  for (const e of errors.slice(0, 5)) console.error(`    ${e.path} ${e.message}`)
}
if (rejected > 0) process.exit(1)
console.log(`✓ manifest.schema.json accepts all ${shipped.length} shipped manifests`)

// 8. The Part SDK level (src/core/parts/partSdk.ts): a part is stamped with the level it was changed under, and an older
// build warns about it, so the level has to move whenever the surface does. levels.json records a hash of each level's
// surface (the declarations without comments, the schema without descriptions, so a doc edit is not a new level).
// A recorded level is never rewritten: a surface that no longer matches it needs the next level.
{
  const levelMatch = /export const PART_SDK_LEVEL = (\d+)/.exec(readFileSync(resolve(root, 'src/core/parts/partSdk.ts'), 'utf8'))
  if (!levelMatch) throw new Error('PART_SDK_LEVEL not found in src/core/parts/partSdk.ts')
  const level = Number(levelMatch[1])
  const printer = ts.createPrinter({ removeComments: true })
  const bare = (name) => printer.printFile(ts.createSourceFile(name, outputs.get(name), ts.ScriptTarget.ES2022, true))
  const undescribed = (v) =>
    Array.isArray(v) ? v.map(undescribed)
    : v !== null && typeof v === 'object' ? Object.fromEntries(Object.entries(v).filter(([k]) => k !== 'description').map(([k, x]) => [k, undescribed(x)]))
    : v
  const surface = createHash('sha256')
    .update(bare('index.d.ts'))
    .update(bare('manifest.d.ts'))
    .update(JSON.stringify(undescribed(JSON.parse(outputs.get('manifest.schema.json')))))
    .digest('hex')

  const ledgerPath = resolve(outDir, 'levels.json')
  const ledger = existsSync(ledgerPath) ? JSON.parse(readFileSync(ledgerPath, 'utf8')) : {}
  const highest = Math.max(0, ...Object.keys(ledger).map(Number))
  if (level < highest) {
    console.error(`✗ PART_SDK_LEVEL is ${level}, below level ${highest} in packages/part-sdk/levels.json`)
    process.exit(1)
  }
  if (ledger[level] !== undefined && ledger[level] !== surface) {
    console.error(`✗ the Part SDK surface changed since level ${level} was recorded: raise PART_SDK_LEVEL in src/core/parts/partSdk.ts to ${level + 1}, then rerun`)
    process.exit(1)
  }
  if (ledger[level] === undefined) {
    if (check) {
      console.error(`✗ Part SDK level ${level} is not recorded in packages/part-sdk/levels.json - run \`npm run build-part-sdk\``)
      stale++
    } else {
      ledger[level] = surface
      writeFileSync(ledgerPath, JSON.stringify(ledger, null, 2) + '\n')
      console.log(`✓ recorded Part SDK level ${level} in packages/part-sdk/levels.json`)
    }
  }

  // the published package's version follows the level, so an author's installed types say which builds read them
  const pkgJsonPath = resolve(outDir, 'package.json')
  const pkgJson = JSON.parse(readFileSync(pkgJsonPath, 'utf8'))
  const version = `0.${level}.0`
  if (pkgJson.version !== version) {
    if (check) {
      console.error(`✗ packages/part-sdk/package.json version is ${pkgJson.version}, expected ${version} for Part SDK level ${level} - run \`npm run build-part-sdk\``)
      stale++
    } else {
      pkgJson.version = version
      writeFileSync(pkgJsonPath, JSON.stringify(pkgJson, null, 2) + '\n')
      console.log(`✓ set packages/part-sdk/package.json version to ${version}`)
    }
  }
}

if (check) {
  if (stale > 0) process.exit(1)
  console.log('✓ packages/part-sdk is up to date')
}
